// Generated by nexa2vue: runtime helpers that emulate the Nexacro APIs used by
// converted screens. Datasets are Vue refs holding an array of row objects.
// Review `config` and the TODO stubs before using in production.

export const config = {
  // Map a Nexacro service URL ("svc::member/list.do") to a real endpoint.
  resolveUrl: (url) => '/' + String(url).replace(/^[\w-]+::/, ''),
  request: async (url, body) => {
    const res = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return res.json();
  },
};

export function http(url, params) {
  return config.request(config.resolveUrl(url), params);
}

const clone = (v) => JSON.parse(JSON.stringify(v));

export const ds = {
  getRowCount: (d) => d.value.length,
  getColumn: (d, row, col) => (d.value[row] ? d.value[row][col] : undefined),
  setColumn(d, row, col, val) {
    if (!d.value[row]) return false;
    d.value[row][col] = val;
    return true;
  },
  addRow(d) {
    d.value.push({});
    d.rowposition = d.value.length - 1;
    return d.rowposition;
  },
  insertRow(d, idx) {
    const at = Math.max(0, Math.min(idx, d.value.length));
    d.value.splice(at, 0, {});
    return at;
  },
  deleteRow(d, idx) {
    if (idx < 0 || idx >= d.value.length) return false;
    d.value.splice(idx, 1);
    return true;
  },
  deleteAll(d) {
    const n = d.value.length;
    d.value = [];
    return n;
  },
  clearData(d) {
    d.value = [];
  },
  copyData(d, src) {
    d.value = clone(src.value);
    return d.value.length;
  },
  appendData(d, src) {
    d.value.push(...clone(src.value));
    return d.value.length;
  },
  findRow(d, col, val, start = 0, end = -1) {
    const last = end < 0 ? d.value.length - 1 : end;
    for (let i = start; i <= last; i++) if (d.value[i] && d.value[i][col] == val) return i;
    return -1;
  },
  getSum(d, col, start = 0, end = -1) {
    const last = end < 0 ? d.value.length - 1 : end;
    let sum = 0;
    for (let i = start; i <= last; i++) sum += Number(d.value[i] ? d.value[i][col] : 0) || 0;
    return sum;
  },
};

/**
 * Emulates this.transaction(svcId, url, inDatasets, outDatasets, args, callback).
 * inMap:  { serverName: datasetRef }   outMap: { serverName: datasetRef }
 */
export async function transaction(svcId, apiFn, inMap, outMap, args, callback) {
  const body = { args };
  for (const [server, ref] of Object.entries(inMap)) body[server] = ref.value;
  try {
    const res = await apiFn(body);
    for (const [server, ref] of Object.entries(outMap)) {
      ref.value = res && Array.isArray(res[server]) ? res[server] : [];
    }
    if (callback) callback(svcId, 0, '');
  } catch (err) {
    if (callback) callback(svcId, -1, err && err.message ? err.message : String(err));
  }
}

export function focus(id) {
  const el = document.querySelector(`[data-nexa-id="${id}"]`);
  const input = el && (el.matches('input,textarea,button') ? el : el.querySelector('input,textarea,button'));
  if (input) input.focus();
}

